/** Decorate only the exact native factory inspected by this Host. */
function inboxInstallBridge(owner, expectedFactory, adaptedFactory, details) {
  const loader = window.__ModuleLoader__;
  const listeners = new Set();
  let active = 0;
  let fault;
  let suspended = false;
  let originalDescriptor;
  let currentLoad;
  let wrappedLoad;
  let getLoad;
  let setLoad;
  function notify() {
    for (const listener of [...listeners]) {
      try { listener(); } catch (error) { console.warn('[dsh-session-inbox] Observer failed', error); }
    }
  }
  const state = {
    details,
    get enabled() { return active > 0 && !fault; },
    get reason() { return fault; },
    subscribe(listener) { listeners.add(listener); return () => listeners.delete(listener); },
    fail(reason) {
      if (fault) return;
      fault = reason;
      restore();
      notify();
      console.warn('[dsh-session-inbox] Native list retained:', reason);
    },
    activate() {
      active++;
      suspended = false;
      install();
      notify();
      let disposed = false;
      return () => {
        if (disposed) return;
        disposed = true;
        active--;
        if (active === 0) restore();
        notify();
      };
    },
  };
  window.__DSH_SESSION_INBOX_BRIDGE__ = state;
  const decorated = new WeakSet();
  function decorate(registration) {
    if (suspended || fault || registration?.id !== owner || decorated.has(registration)) return registration;
    if (typeof registration.factory !== 'function'
      || registration.factory.toString().replace(/\r\n/g, '\n') !== expectedFactory) {
      state.fail('native-factory-changed');
      return registration;
    }
    const original = registration.factory;
    const replacement = { ...registration, factory(require) {
      if (fault || suspended) return original(require);
      try { return adaptedFactory(require); }
      catch (error) {
        state.fail('native-factory-unavailable');
        return original(require);
      }
    } };
    decorated.add(replacement);
    return replacement;
  }
  function restore() {
    suspended = true;
    const descriptor = loader && Object.getOwnPropertyDescriptor(loader, 'load');
    if (getLoad && descriptor?.get === getLoad && descriptor?.set === setLoad) {
      Object.defineProperty(loader, 'load', { ...originalDescriptor, value: currentLoad });
    }
  }
  function install() {
    if (fault) return;
    if (typeof loader?.load !== 'function') { state.fail('module-loader-unavailable'); return; }
    const descriptor = Object.getOwnPropertyDescriptor(loader, 'load');
    if (getLoad && descriptor?.get === getLoad && descriptor?.set === setLoad) return;
    if (descriptor && (!descriptor.configurable || !('value' in descriptor) || !descriptor.writable)) {
      state.fail('module-loader-contract-changed'); return;
    }
    originalDescriptor = descriptor ?? { configurable: true, enumerable: true, writable: true };
    const wrap = next => function (registration) { return Reflect.apply(next, this, [decorate(registration)]); };
    currentLoad = loader.load;
    wrappedLoad = wrap(currentLoad);
    getLoad = () => wrappedLoad;
    setLoad = next => {
      currentLoad = next;
      if (typeof next !== 'function') { state.fail('module-loader-contract-changed'); return; }
      wrappedLoad = wrap(next);
    };
    // DSH replaces the parser's queue facade with its live loader during boot.
    // Preserve that assignment and decorate its current target, never a stale queue.
    Object.defineProperty(loader, 'load', { configurable: true, enumerable: originalDescriptor.enumerable, get: getLoad, set: setLoad });
    if (Array.isArray(loader.pendingQueue)) {
      for (let i = 0; i < loader.pendingQueue.length; i++) loader.pendingQueue[i] = decorate(loader.pendingQueue[i]);
    }
  }
  install();
}

shared:
/** Pure presentation state. No session, archive, task or transcript is ever mutated here. */
const INBOX_STORAGE_KEY = 'dsh-session-inbox:state:v1';

function inboxEmptyState() {
  return { version: 1, mode: 'inbox', groupByProject: false, includeArchived: true, settled: {}, unread: {}, collapsed: { settled: true } };
}

/** Reject corrupt/future records instead of silently overwriting the user's metadata. */
function inboxParseState(raw) {
  if (raw === null) return inboxEmptyState();
  const value = JSON.parse(raw);
  if (!value || value.version !== 1 || !['inbox', 'original'].includes(value.mode)
      || typeof value.groupByProject !== 'boolean' || !value.settled || !value.collapsed
      || typeof value.settled !== 'object' || typeof value.collapsed !== 'object'
      || Array.isArray(value.settled) || Array.isArray(value.collapsed)) {
    throw new Error('整理记录的格式不受支持，原数据已保留。');
  }
  for (const [id, entry] of Object.entries(value.settled)) {
    if (['__proto__', 'constructor', 'prototype'].includes(id) || !entry
        || typeof entry.stamp !== 'string' || !Number.isFinite(entry.at)) {
      throw new Error('整理记录无法读取，原数据已保留。');
    }
  }
  for (const collapsed of Object.values(value.collapsed)) {
    if (typeof collapsed !== 'boolean') throw new Error('折叠状态无法读取。');
  }
  if (value.includeArchived !== undefined && typeof value.includeArchived !== 'boolean') {
    throw new Error('归档显示选项无法读取。');
  }
  if (value.unread !== undefined) {
    if (!value.unread || typeof value.unread !== 'object' || Array.isArray(value.unread)) throw new Error('未读状态无法读取。');
    for (const [id, at] of Object.entries(value.unread)) {
      if (['__proto__', 'constructor', 'prototype'].includes(id) || !Number.isFinite(at) || at < 0) throw new Error('未读状态无法读取。');
    }
  }
  return { ...value, unread: value.unread ?? {}, includeArchived: value.includeArchived ?? true };
}

function inboxActivityStamp(session) {
  return String(session.updatedAt ?? 0);
}

/** Short labels keep dates from squeezing the conversation title. */
function inboxRelativeTime(timestamp, now = Date.now()) {
  if (!Number.isFinite(timestamp) || timestamp <= 0) return '';
  const minutes = Math.max(0, Math.floor((now - timestamp) / 60_000));
  if (minutes < 1) return '刚刚';
  if (minutes < 60) return `${minutes} 分钟`;
  if (minutes < 1440) return `${Math.floor(minutes / 60)} 小时`;
  const date = new Date(timestamp);
  return `${date.getMonth() + 1}/${date.getDate()}`;
}

/** T3's inbox is untitled; only unattended execution belongs in the lower Working shelf. */
function inboxCategory(row, state) {
  if (row.pending) return 'active';
  if (row.running) return 'working';
  const mark = state.settled[row.id];
  return mark && !inboxHasNewActivity(row, mark) ? 'settled' : 'active';
}

/** Preserve project folds from prior layouts; the untitled inbox itself cannot be collapsed. */
function inboxCollapsed(state, category, projectId) {
  if (category === 'active' && projectId === undefined) return false;
  if (projectId === undefined) return state.collapsed[category === 'working' ? 'running' : category] === true;
  const key = `${category}:${projectId}`;
  const legacy = category === 'active'
    ? state.collapsed[`attention:${projectId}`] ?? state.collapsed[`working:${projectId}`]
    : false;
  return (state.collapsed[key] ?? legacy) === true;
}

/** Finished work and restored chats return to the top without changing durable activity stamps. */
function inboxPartition(rows, state, returnedAt = {}) {
  const groups = { active: [], working: [], settled: [] };
  for (const row of rows) groups[inboxCategory(row, state)].push(row);
  groups.active.sort((a, b) => Number(Boolean(b.pending)) - Number(Boolean(a.pending))
    || Number(b.pinned) - Number(a.pinned)
    || Math.max(b.updatedAt, returnedAt[b.id] ?? 0) - Math.max(a.updatedAt, returnedAt[a.id] ?? 0));
  return groups;
}

/** Lazy history hydration may replace a zero/stale timestamp with an older prompt.
 * Only activity newer than both the recorded prompt and the actual Settle time reopens it. */
function inboxHasNewActivity(row, mark) {
  const current = Number(row.stamp);
  const recorded = Number(mark.stamp);
  return Number.isFinite(current) && current > Math.max(Number.isFinite(recorded) ? recorded : 0, mark.at);
}

function inboxSettle(state, row, now = Date.now()) {
  if (row.running || row.pending || row.blank) return state;
  return { ...inboxAcknowledge(state, row.id), settled: { ...state.settled, [row.id]: { stamp: row.stamp, at: now } } };
}

/** DSH retains the main chat behind global panels. Record completions that were not actually visible. */
function inboxComplete(state, id, now = Date.now()) {
  return { ...state, unread: { ...state.unread, [id]: now } };
}

function inboxAcknowledge(state, id) {
  if (!Object.hasOwn(state.unread ?? {}, id)) return state;
  const unread = { ...state.unread };
  delete unread[id];
  return { ...state, unread };
}

function inboxRestore(state, id) {
  const settled = { ...state.settled };
  delete settled[id];
  return { ...state, settled };
}

/** Missing catalog rows may be reconnecting. Never erase their metadata during a partial baseline. */
function inboxReconcile(state, rows) {
  let next = state;
  for (const row of rows) {
    if (row.running) next = inboxAcknowledge(next, row.id);
    const mark = next.settled[row.id];
    if (mark && (row.running || row.pending || inboxHasNewActivity(row, mark))) {
      next = inboxRestore(next, row.id);
    }
  }
  return next;
}

/** Project membership comes from DSH, not from guesses about titles or folder names. */
function inboxRows(list, workspaces, statuses, archivedIds, pinnedIds, preservedBlankIds = []) {
  const projects = new Map();
  for (const workspace of workspaces) {
    for (const id of workspace.sessionIds) projects.set(id, workspace);
  }
  const archived = new Set(archivedIds);
  const pinned = new Set(pinnedIds);
  const preservedBlanks = new Set(preservedBlankIds);
  // Grouped membership may arrive before the flat catalog during a reconnect.
  const ids = [...new Set([...workspaces.flatMap(project => project.sessionIds), ...list.ids])];
  return ids.flatMap(id => {
    const session = list.byId[id];
    if (!session || session.origin === 'subagent' || (session.blank && !preservedBlanks.has(id))) return [];
    const status = statuses.get(id);
    const children = list.projectionsBySession?.[id]?.values?.subagentCatalog ?? [];
    const runningSubagentCount = children.filter(child => (statuses.get(child.id)?.running ?? list.byId[child.id]?.running) === true).length;
    const project = projects.get(id);
    return [{
      id, title: session.blank ? '空会话' : (session.title?.trim() || '未命名会话'),
      stamp: inboxActivityStamp(session), updatedAt: Number(session.updatedAt) || 0,
      blank: session.blank === true, archived: archived.has(id), pinned: pinned.has(id),
      running: (status?.running ?? session.running) === true || runningSubagentCount > 0, runningSubagentCount,
      pending: status?.pendingInteraction?.kind ?? null,
      completionUnread: status?.completionUnread === true,
      projectId: project?.workspaceId ?? '', projectTitle: project?.title ?? '未分组',
      path: project?.path ?? '',
    }];
  }).sort((a, b) => Number(b.pinned) - Number(a.pinned) || b.updatedAt - a.updatedAt || a.id.localeCompare(b.id));
}

function inboxFilterRows(rows, query, projectId, includeArchived) {
  const search = query.trim().toLocaleLowerCase();
  return rows.filter(row => (includeArchived || !row.archived)
    && (projectId === '*' || row.projectId === projectId)
    && (!search || `${row.title} ${row.projectTitle} ${row.path}`.toLocaleLowerCase().includes(search)));
}

/** Search reveals matches temporarily; it never changes the saved shelf or project folds. */
function inboxViewCollapsed(state, category, query, projectId) {
  return query.trim() ? false : inboxCollapsed(state, category, projectId);
}

/** Literal text pieces only: highlighting must never interpret a title or query as HTML. */
function inboxHighlight(text, query) {
  const needle = query.trim();
  if (!needle) return [{ text, match: false }];
  const escaped = needle.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const expression = new RegExp(escaped, 'giu');
  const pieces = [];
  let offset = 0;
  for (const match of text.matchAll(expression)) {
    if (match.index > offset) pieces.push({ text: text.slice(offset, match.index), match: false });
    pieces.push({ text: match[0], match: true });
    offset = match.index + match[0].length;
  }
  if (offset < text.length) pieces.push({ text: text.slice(offset), match: false });
  return pieces;
}

/** Portable list metadata only. No titles, paths, conversation bodies, account data or credentials. */

const INBOX_BACKUP_LIMIT = 2 * 1024 * 1024;

function inboxExportBackup(state, now = Date.now()) {
  const parsed = inboxParseState(JSON.stringify(state));
  return JSON.stringify({ format: 'dsh-session-inbox-backup', version: 1,
    exportedAt: new Date(now).toISOString(), state: {
      version: parsed.version, mode: 'inbox', groupByProject: parsed.groupByProject,
      includeArchived: parsed.includeArchived, collapsed: parsed.collapsed, settled: parsed.settled,
    },
  }, null, 2) + '\n';
}

/** Validate the entire file before any write; unknown formats cannot reset live metadata. */
function inboxParseBackup(text) {
  if (text.length > INBOX_BACKUP_LIMIT) throw new Error('备份文件过大，最多支持 2 MB。');
  const value = JSON.parse(text);
  if (!value || value.format !== 'dsh-session-inbox-backup' || value.version !== 1
      || typeof value.exportedAt !== 'string' || !Number.isFinite(Date.parse(value.exportedAt))) {
    throw new Error('这不是受支持的会话工作台备份。');
  }
  const state = inboxParseState(JSON.stringify(value.state));
  if (Object.keys(state.settled).length > 20_000) throw new Error('备份中的整理记录过多。');
  return { exportedAt: value.exportedAt, state };
}

/** Merge rather than replace: keep current records and never hide new activity or unattended work. */
function inboxMergeBackup(current, backup, rows, restorePreferences = false) {
  const settled = { ...current.settled };
  for (const [id, mark] of Object.entries(backup.state.settled)) {
    if (!settled[id] || mark.at > settled[id].at) settled[id] = { ...mark };
  }
  const preferences = restorePreferences ? {
    groupByProject: backup.state.groupByProject,
    includeArchived: backup.state.includeArchived,
    collapsed: { ...backup.state.collapsed },
  } : {};
  return inboxReconcile({ ...current, ...preferences, settled }, rows);
}

/** Keep the sidebar shell and list in sync without changing DSH's navigation or draft state. */
const INBOX_STATE_EVENT = 'dsh-session-inbox:change';
let inboxModeOverride;

function inboxPublishMode(mode) {
  inboxModeOverride = mode;
  window.dispatchEvent(new Event(INBOX_STATE_EVENT));
}

function inboxReadModeSnapshot() {
  if (inboxModeOverride !== undefined) return inboxModeOverride;
  try { return inboxParseState(localStorage.getItem(INBOX_STORAGE_KEY)).mode; }
  catch { return 'inbox'; }
}

function inboxSubscribeMode(listener) {
  const onStorage = event => {
    if (event.key !== INBOX_STORAGE_KEY) return;
    inboxModeOverride = undefined;
    listener();
  };
  window.addEventListener('storage', onStorage);
  window.addEventListener(INBOX_STATE_EVENT, listener);
  return () => {
    window.removeEventListener('storage', onStorage);
    window.removeEventListener(INBOX_STATE_EVENT, listener);
  };
}

/** Resolve the official shell's current CSS-module hashes, rather than the vendored build's hashes. */
function inboxResolveShellCss(template) {
  const owner = '@deepseek-ai/dsh-client-ui-sidebar';
  const sheets = [...document.querySelectorAll(`style[data-plugin-css="${owner}/SidebarRoot.module.css"]`)]
    .filter(style => style.dataset.plugin === owner);
  if (sheets.length !== 1) throw new Error('Session workbench requires one loaded native SidebarRoot stylesheet.');
  const classes = {};
  // These wrappers were introduced after the first supported sidebar. Their
  // optional styling must not prevent older native layouts from mounting.
  const optional = new Set(['newSessionContent', 'newSessionLabelMask', 'newSessionShortcut', 'moreAnchor']);
  for (const key of ['root', 'collapsed', 'topStrip', 'logoRow', 'brandIdentity', 'brandMark', 'brandName', 'newSession',
    'newSessionContent', 'newSessionLabel', 'newSessionLabelMask', 'newSessionShortcut', 'panelList', 'panelRow',
    'panelGlyph', 'panelTitle', 'moreAnchor', 'regionArea', 'footArea']) {
    const matches = [...new Set([...sheets[0].textContent.matchAll(new RegExp(`\\.([_a-zA-Z][-\\w]*_${key})(?![-\\w])`, 'g'))]
      .map(match => match[1]))];
    if (matches.length > 1 || (matches.length === 0 && !optional.has(key))) {
      throw new Error(`Unsupported native sidebar stylesheet: missing or ambiguous ${key} class.`);
    }
    classes[key] = matches[0] ?? `dsi-absent-${key}`;
  }
  const scope = `html[data-inbox-mode="inbox"] .${classes.root}:not(.${classes.collapsed})`;
  let css = template.replaceAll('.dsi-shell-compact .dsi-shell-root', scope)
    .replaceAll('.dsi-shell-compact ', `${scope} `);
  for (const [key, className] of Object.entries(classes)) {
    const alias = key.replace(/[A-Z]/g, letter => '-' + letter.toLowerCase());
    css = css.replace(new RegExp(`\\.dsi-shell-${alias}(?![-a-z])`, 'g'), `.${className}`);
  }
  return css;
}

/** Retain the official shell and all its plugin seats; scope presentation overrides to workbench mode. */
function inboxInstallShell(ctx) {
  ctx.effect(() => {
    const css = inboxResolveShellCss(INBOX_CSS);
    // Native fallback sheets share the plugin ID; replace only the compact shell's own sheet.
    const selector = 'style[data-inbox-shell="dsh-session-inbox"]';
    document.querySelectorAll(selector).forEach(style => style.remove());
    const style = document.createElement('style');
    style.dataset.plugin = 'dsh-session-inbox';
    style.dataset.inboxShell = 'dsh-session-inbox';
    style.textContent = css;
    document.head.appendChild(style);
    const bridge = window.__DSH_SESSION_INBOX_BRIDGE__;
    const render = () => {
      const enabled = bridge?.enabled !== false;
      if (enabled && ![...document.querySelectorAll(selector)].includes(style)) document.head.appendChild(style);
      document.documentElement.dataset.inboxMode = enabled ? inboxReadModeSnapshot() : 'original';
    };
    render();
    const unsubscribe = inboxSubscribeMode(render);
    const unsubscribeBridge = bridge?.subscribe(render);
    return () => {
      unsubscribe();
      unsubscribeBridge?.();
      // A previous module can dispose after its replacement has already taken ownership.
      if ([...document.querySelectorAll(selector)].includes(style)) delete document.documentElement.dataset.inboxMode;
      style.remove();
    };
  }, 'session-inbox: compact native shell');
}
